CREATE TABLE distributions(
  id_distribution INTEGER PRIMARY KEY, code_ecole TEXT NOT NULL, id_eleve INTEGER,
  date_distribution DATE, type_kit TEXT, quantite INTEGER,
  FOREIGN KEY(code_ecole) REFERENCES ecoles(code_ecole), FOREIGN KEY(id_eleve) REFERENCES eleves(id_eleve));
