CREATE TABLE ecoles(
  code_ecole TEXT PRIMARY KEY, nom_ecole TEXT NOT NULL, id_region INTEGER NOT NULL,
  commune TEXT, milieu TEXT CHECK(milieu IN ('Rural','Peri-urbain')),
  nb_salles INTEGER CHECK(nb_salles>0), cantine TEXT CHECK(cantine IN ('Oui','Non')),
  eau_potable TEXT CHECK(eau_potable IN ('Oui','Non')),
  FOREIGN KEY(id_region) REFERENCES regions(id_region));
