CREATE TABLE eleves(
  id_eleve INTEGER PRIMARY KEY, code_ecole TEXT NOT NULL, nom TEXT NOT NULL, prenom TEXT NOT NULL,
  sexe TEXT CHECK(sexe IN ('F','M')), date_naissance DATE, parraine INTEGER NOT NULL CHECK(parraine IN (0,1)),
  date_inscription DATE, statut TEXT CHECK(statut IN ('actif','abandon','transfere')),
  FOREIGN KEY(code_ecole) REFERENCES ecoles(code_ecole));
