CREATE TABLE suivi_hebdo(
  id_suivi INTEGER PRIMARY KEY, code_ecole TEXT NOT NULL, semaine INTEGER NOT NULL CHECK(semaine BETWEEN 1 AND 52),
  date_saisie DATE, jours_classe INTEGER CHECK(jours_classe BETWEEN 0 AND 6),
  eleves_inscrits INTEGER, eleves_presents INTEGER, eleves_presents_parraines INTEGER,
  repas_servis INTEGER, enseignants_prevus INTEGER, enseignants_presents INTEGER,
  FOREIGN KEY(code_ecole) REFERENCES ecoles(code_ecole),
  UNIQUE(code_ecole,semaine));
